/**
 * Client-safe contract for POST /api/demo/reset (FS-17).
 *   POST /api/demo/reset (empty body) -> apiSuccessSchema(DemoResetDataSchema)
 * Allowed only when DEMO_MODE is enabled on the server AND the request is local
 * (loopback Host, same-origin browser request). See src/app/api/_lib/demo-reset.ts.
 */
import * as z from "zod";
import { IsoDateTimeSchema } from "../schema/primitives";

export const DEMO_RESET_NOTICE =
  "Demo data restored to the fictional Northstar Labs fixture. Simulations, proposals and audit history were cleared; incidents were regenerated by the risk engine.";

const Count = z.int().nonnegative();

export const DemoResetDataSchema = z.strictObject({
  fixture: z.strictObject({ id: z.string(), version: z.int().positive() }),
  /** Rows removed per table. */
  cleared: z.strictObject({
    auditEvents: Count,
    incidents: Count,
    simulations: Count,
    actionProposals: Count,
    edges: Count,
    nodes: Count,
    transactions: Count,
    vendorCharges: Count,
    paymentInstruments: Count,
    vendors: Count,
    fundingSources: Count,
    workspaces: Count,
    evidence: Count,
  }),
  /** Fixture rows recreated per collection. */
  recreated: z.strictObject({
    workspaces: Count,
    evidence: Count,
    fundingSources: Count,
    paymentInstruments: Count,
    vendors: Count,
    vendorCharges: Count,
    transactions: Count,
    nodes: Count,
    edges: Count,
  }),
  /** Incidents regenerated by the risk engine at the demo clock. */
  incidents: z.strictObject({ regenerated: Count, incidentIds: z.array(z.string()), evaluatedAt: IsoDateTimeSchema }),
  notice: z.literal(DEMO_RESET_NOTICE),
});
export type DemoResetData = z.infer<typeof DemoResetDataSchema>;
